$gameRoot = Split-Path -Parent $patchRoot
$source = Join-Path $patchRoot 'backup\L_ENGLIS.original.CRK'
$target = Join-Path $gameRoot 'data\CRK\L_ENGLIS.CRK'
$encoding = [Text.Encoding]::GetEncoding(1251)

$encoded = [IO.File]::ReadAllBytes($source)
$decoded = [byte[]]::new($encoded.Length)
for ($i = 0; $i -lt $encoded.Length; $i++) {
    $decoded[$i] = ($encoded[$i] - 127) -band 0xFF
}

$text = $encoding.GetString($decoded)
function From-Cp1251([int[]]$bytes) {
    return $encoding.GetString([byte[]]$bytes)
}

