foreach ($entry in $translations.GetEnumerator()) {
    $pattern = '(?m)^(' + [regex]::Escape($entry.Key) + '\s*=\s*).*$'
    $matches = [regex]::Matches($text, $pattern)
    $expectedCount = if ($entry.Key -eq 'CS_CANONS') { 3 } else { 1 }
    if ($matches.Count -ne $expectedCount) {
        throw "Expected $expectedCount record(s) for $($entry.Key), found $($matches.Count)."
    }
    $replacement = '${1}' + $entry.Value
    $text = [regex]::Replace($text, $pattern, $replacement)
}

$plain = $encoding.GetBytes($text)
$result = [byte[]]::new($plain.Length)
for ($i = 0; $i -lt $plain.Length; $i++) {
    $result[$i] = ($plain[$i] + 127) -band 0xFF
}

[IO.File]::WriteAllBytes($target, $result)
Write-Host 'Russian menu and gameplay-interface strings installed.'
